Next site
0{"show_updated":0,"show_description":1,"show_images":1,"show_name":1,"before":"<li>","after":"<\/li>","between":"\n","show_rating":1,"link_before":"","link_after":"","orderby":"name","order":"ASC","limit":15,"category":O,"exclude_category":"","category_name":"","hide_invisible":1,"echo":1,"categorize":1,"title_li":"Bookmarks","title_before":"<h2 class=\"widget-title\">","title after":"<\/h2>","category_orderby":"name","category_order":"ASC","class":"linkcat widget","category_before":"<section id=\"%id\" class=\"widget widget_links\">","category_after":"<\/section>"}
